from pathlib import Path
from PIL import Image,ImageOps,ImageDraw
p=Path(r'$CANDIDATE/input/learner_cards')
canvas=Image.new('RGB',(1280,4*390),'white'); d=ImageDraw.Draw(canvas)
for i,card in enumerate(['RC01','RC02','RC03','RC04']):
 for j,f in enumerate(sorted(p.glob(card+'*'))):
  im=Image.open(f);print(f.name,im.size)
  if card=='RC02': im=ImageOps.mirror(im)
  if card=='RC03': im=im.rotate(180)
  im.thumbnail((630,355));canvas.paste(im,(j*640,i*390+25));d.text((j*640+10,i*390+5),f.name+' normalized',fill='black')
canvas.save('cards_normalized.jpg')

